import { test, expect } from '@playwright/test';

test.describe('Accessibility - Click Targets Size', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('Verify click targets are at least 44x44px', async ({ page }) => {
    const buttons = await page.getByRole('button');
    for (const button of buttons) {
      const box = await button.boundingBox();
      expect(box).toBeTruthy();
      expect(box.width).toBeGreaterThanOrEqual(44);
      expect(box.height).toBeGreaterThanOrEqual(44);
    }
  });

  test('Verify links are at least 44x44px', async ({ page }) => {
    const links = await page.getByRole('link');
    for (const link of links) {
      const box = await link.boundingBox();
      expect(box).toBeTruthy();
      expect(box.width).toBeGreaterThanOrEqual(44);
      expect(box.height).toBeGreaterThanOrEqual(44);
    }
  });
});
